/**
 * Favicons, embedded so the panel stays zero-CDN.
 *
 * Data, not code. It used to be split across 1778 lines of concatenated
 * string literals -- which made this the third-largest source file in the
 * repository and put 154 KB of icon between two people reading anything near
 * it. One line per asset says the same thing and reads as what it is.
 *
 * Served by mcp/server.ts at /favicon.ico, /icon.png and /apple-touch-icon.png.
 * If an icon is ever replaced, the diff is one line per asset rather than
 * hundreds, which is also the honest shape of that change.
 */

export const FAVICON_ICO_B64 =
  ''

export const ICON_PNG_B64 =
  ''

export const APPLE_TOUCH_B64 =
  ''
